package com.secureauth.core

import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.util.Base64
import java.nio.ByteBuffer
import java.time.Instant

object AuthConfig {
  val MAX_LOGIN_ATTEMPTS: Int = 5
  val LOCKOUT_WINDOW_SECONDS: Int = 300
  val TOKEN_VALIDITY_SECONDS: Int = 3600
  val AES_KEY_SIZE: Int = 256
  val GCM_TAG_LENGTH: Int = 128
  val GCM_IV_LENGTH: Int = 12
}

case class UserCredential(
  userId: String,
  encryptedPassword: Array[Byte],
  salt: Array[Byte],
  failedAttempts: Int,
  lastFailedAt: Long,
  tokenGeneration: Int
)

class SecureTokenStore(masterKey: Array[Byte]) {
  require(masterKey.length == 32, "Master key must be 256 bits")

  private val keySpec = new SecretKeySpec(masterKey, "AES")
  private val random = new SecureRandom()

  def encrypt(plaintext: Array[Byte]): Array[Byte] = {
    val iv = new Array[Byte](AuthConfig.GCM_IV_LENGTH)
    random.nextBytes(iv)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val paramSpec = new GCMParameterSpec(AuthConfig.GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, paramSpec)
    val ciphertext = cipher.doFinal(plaintext)
    iv ++ ciphertext
  }

  def decrypt(data: Array[Byte]): Option[Array[Byte]] = {
    try {
      val iv = data.take(AuthConfig.GCM_IV_LENGTH)
      val ciphertext = data.drop(AuthConfig.GCM_IV_LENGTH)
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      val paramSpec = new GCMParameterSpec(AuthConfig.GCM_TAG_LENGTH, iv)
      cipher.init(Cipher.DECRYPT_MODE, keySpec, paramSpec)
      Some(cipher.doFinal(ciphertext))
    } catch {
      case _: Exception => None
    }
  }
}

class AuthenticationService(store: SecureTokenStore) {
  private var credentials: Map[String, UserCredential] = Map.empty

  def registerUser(userId: String, passwordHash: Array[Byte], salt: Array[Byte]): Unit = {
    val encPwd = store.encrypt(passwordHash)
    credentials = credentials + (userId -> UserCredential(
      userId = userId,
      encryptedPassword = encPwd,
      salt = salt,
      failedAttempts = 0,
      lastFailedAt = 0L,
      tokenGeneration = 0
    ))
  }

  private def computeRemainingAttempts(cred: UserCredential): Int = {
    val now = Instant.now().getEpochSecond
    val elapsed = now - cred.lastFailedAt
    if (elapsed > AuthConfig.LOCKOUT_WINDOW_SECONDS) {
      AuthConfig.MAX_LOGIN_ATTEMPTS
    } else {
      AuthConfig.MAX_LOGIN_ATTEMPTS - cred.failedAttempts
    }
  }

  private def isAccountLocked(cred: UserCredential): Boolean = {
    val remaining = computeRemainingAttempts(cred)
    remaining <= 0
  }

  def authenticate(userId: String, passwordHash: Array[Byte]): Either[String, Array[Byte]] = {
    credentials.get(userId) match {
      case None => Left("Invalid credentials")
      case Some(cred) =>
        if (isAccountLocked(cred)) {
          Left("Account temporarily locked")
        } else {
          store.decrypt(cred.encryptedPassword) match {
            case None => Left("Internal error")
            case Some(storedHash) =>
              if (java.util.Arrays.equals(storedHash, passwordHash)) {
                val updatedCred = cred.copy(failedAttempts = 0, lastFailedAt = 0L)
                credentials = credentials + (userId -> updatedCred)
                Right(generateToken(updatedCred))
              } else {
                recordFailedAttempt(cred)
                Left("Invalid credentials")
              }
          }
        }
    }
  }

  private def recordFailedAttempt(cred: UserCredential): Unit = {
    val now = Instant.now().getEpochSecond
    val elapsed = now - cred.lastFailedAt

    val newFailedAttempts = if (elapsed > AuthConfig.LOCKOUT_WINDOW_SECONDS) {
      1
    } else {
      cred.failedAttempts + 1
    }

    val updatedCred = cred.copy(
      failedAttempts = newFailedAttempts,
      lastFailedAt = now
    )
    credentials = credentials + (cred.userId -> updatedCred)
  }

  private def generateToken(cred: UserCredential): Array[Byte] = {
    val now = Instant.now().getEpochSecond
    val expiry = now + AuthConfig.TOKEN_VALIDITY_SECONDS
    val generation = cred.tokenGeneration

    val payload = ByteBuffer.allocate(28)
    payload.put(cred.userId.getBytes("UTF-8").take(8).padTo(8, 0.toByte))
    payload.putLong(expiry)
    payload.putInt(generation)
    payload.putLong(now)

    store.encrypt(payload.array())
  }

  def validateToken(token: Array[Byte]): Option[String] = {
    store.decrypt(token).flatMap { payload =>
      val buffer = ByteBuffer.wrap(payload)
      val userIdBytes = new Array[Byte](8)
      buffer.get(userIdBytes)
      val userId = new String(userIdBytes, "UTF-8").trim
      val expiry = buffer.getLong()
      val generation = buffer.getInt()
      val now = Instant.now().getEpochSecond

      credentials.get(userId).flatMap { cred =>
        if (now < expiry && generation == cred.tokenGeneration) {
          Some(userId)
        } else {
          None
        }
      }
    }
  }

  def revokeAllTokens(userId: String): Unit = {
    credentials.get(userId).foreach { cred =>
      val updatedCred = cred.copy(tokenGeneration = cred.tokenGeneration + 1)
      credentials = credentials + (userId -> updatedCred)
    }
  }

  def getRemainingAttempts(userId: String): Option[Int] = {
    credentials.get(userId).map(computeRemainingAttempts)
  }

  def resetLockout(userId: String, adminToken: Array[Byte]): Either[String, Unit] = {
    validateToken(adminToken) match {
      case None => Left("Invalid admin token")
      case Some(_) =>
        credentials.get(userId) match {
          case None => Left("User not found")
          case Some(cred) =>
            val updatedCred = cred.copy(failedAttempts = 0, lastFailedAt = 0L)
            credentials = credentials + (userId -> updatedCred)
            Right(())
        }
    }
  }
}
